using System.Text.Json.Serialization;

namespace Elevant.Contracts.Integration;

/// <summary>
/// «Disparar vuelo demo» (ADR-0041). <paramref name="DestinationIata"/> null is the origin: the aircraft returns where
/// it came from. <paramref name="StandChoice"/> is <c>None</c> or <c>Specific</c> (with <paramref name="StandId"/>);
/// the flight numbers and the registration are generated by the server, never typed.
/// </summary>
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
public sealed record CreateDemoFlightRequest(Guid StationId, Guid AirlineId, string OriginIata, string? DestinationIata,
    Guid AircraftTypeId, string StandChoice, Guid? StandId, int MinutesToOnBlock, int GroundMinutes);

/// <summary>
/// «Cancelar vuelo» (<c>Cancel</c>, before touchdown) or «Terminar demo» (<c>Finish</c>, after it). The intent is
/// checked against the phase of the flight; there is no expected version because the progress worker's stamps make
/// row versions stale by design.
/// </summary>
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
public sealed record CancelDemoFlightRequest(string Intent);

/// <summary>
/// A demo flight as the superadministrator follows it. <paramref name="State"/> is Active, Cancelled or Finished and
/// <paramref name="Phase"/> Approach, TaxiIn, Parked, TaxiOut, Departed or Gone, at the server time of the answer.
/// Every instant comes from the server's demo clock: no screen derives one. <paramref name="SuggestedStandCode"/> is
/// the stand the trigger proposed; once OCC imported the flight (<paramref name="Imported"/>) the turnaround, its
/// operation and the stand OCC assigned follow.
/// </summary>
public sealed record DemoFlightResponse(Guid Id, Guid StationId, string StationCode, Guid AirlineId, string AirlineName,
    string ArrivalFlightNumber, string DepartureFlightNumber, string AircraftRegistration, string AircraftModel,
    string OriginIata, string DestinationIata, string? SuggestedStandCode, string State, string Phase,
    DateTimeOffset AppearAt, DateTimeOffset TouchdownAt, DateTimeOffset OnBlockAt, DateTimeOffset ScheduledOffBlockAt,
    DateTimeOffset? OffBlockAt, DateTimeOffset? TakeoffAt, DateTimeOffset? VanishAt, bool Imported, Guid? TurnaroundId,
    string? OperationCode, string? StandCode, string? OperationStatus);

/// <summary>
/// The demo flights of the last 24 hours at a station, newest first (at most 50). With the feature off in this
/// environment <paramref name="Enabled"/> is false and the list is empty.
/// </summary>
public sealed record DemoFlightListResponse(bool Enabled, DateTimeOffset ServerTime, Guid? StationId,
    IReadOnlyList<DemoFlightResponse> Flights);

/// <summary>
/// What the form «Disparar vuelo demo» offers at a station: the airlines with exactly one applicable contract on
/// <paramref name="OperationDate"/> (the station's local day), the airports, the active aircraft types and stands, the
/// limits and the warnings that never block. With the feature off <paramref name="Enabled"/> is false and every list
/// is empty.
/// </summary>
public sealed record DemoFlightOptionsResponse(bool Enabled, DateTimeOffset ServerTime,
    IReadOnlyList<DemoStationOptionResponse> Stations, Guid? StationId, DateOnly? OperationDate,
    IReadOnlyList<DemoAirlineOptionResponse> Airlines, IReadOnlyList<DemoAirportOptionResponse> Airports,
    IReadOnlyList<DemoAircraftTypeOptionResponse> AircraftTypes, IReadOnlyList<DemoStandOptionResponse> Stands,
    DemoFlightLimitsResponse Limits, IReadOnlyList<DemoFlightWarningResponse> Warnings);

public sealed record DemoStationOptionResponse(Guid Id, string Code, string Name);

public sealed record DemoAirlineOptionResponse(Guid Id, string Name, string? IataCode, string IcaoCode);

public sealed record DemoAirportOptionResponse(string IataCode, string IcaoCode, string Name, string City,
    string CountryCode);

/// <summary><paramref name="SizeCategory"/> is Narrowbody, Widebody or null when unknown.</summary>
public sealed record DemoAircraftTypeOptionResponse(Guid Id, string IcaoCode, string Manufacturer, string Model,
    string? SizeCategory);

/// <summary>
/// An active stand of an active terminal. <paramref name="Free"/>: nothing occupies it during the visit and no other
/// active demo flight suggests it.
/// </summary>
public sealed record DemoStandOptionResponse(Guid StandId, string Code, string TerminalCode, bool Free);

/// <summary>The ranges of the form and how many demo flights are active at the station out of <paramref name="MaxActive"/>.</summary>
public sealed record DemoFlightLimitsResponse(int MinMinutesToOnBlock, int MaxMinutesToOnBlock, int DefaultMinutesToOnBlock,
    int MinGroundMinutes, int MaxGroundMinutes, int DefaultGroundMinutes, int MaxActive, int Active);

/// <summary>Something the superadministrator should know before triggering; it never blocks the command.</summary>
public sealed record DemoFlightWarningResponse(string Code, IReadOnlyList<string> Reasons);
